    row_scores = [sum(v == 8 for v in row) / w for row in a]
    col_scores = [sum(a[r][c] == 8 for r in range(h)) / h for c in range(w)]
    horizontal = max(row_scores) >= max(col_scores)

    if horizontal:
        barriers = [r for r, score in enumerate(row_scores)
